import { ValueDuplicationError } from './errors.mjs';
import { formatBidictRepresentation } from './python-repr.mjs';

function findKeyIndex(entries, key) {
  for (let index = 0; index < entries.length; index += 1) {
    if (entries[index].key === key) {
      return index;
    }
  }

  return -1;
}

function findValueIndex(entries, value) {
  for (let index = 0; index < entries.length; index += 1) {
    if (entries[index].value === value) {
      return index;
    }
  }

  return -1;
}

export function collapseLiteralPairs(pairs) {
  const entries = [];

  for (const [key, value] of pairs) {
    const keyIndex = findKeyIndex(entries, key);

    if (keyIndex === -1) {
      entries.push({ key, value });
    } else {
      entries[keyIndex].value = value;
    }
  }

  return entries;
}

export class Bidict {
  constructor(entries = []) {
    this._entries = [];

    for (const { key, value } of entries) {
      if (findValueIndex(this._entries, value) !== -1) {
        throw new ValueDuplicationError(value, 'init');
      }

      const keyIndex = findKeyIndex(this._entries, key);

      if (keyIndex === -1) {
        this._entries.push({ key, value });
      } else {
        this._entries[keyIndex].value = value;
      }
    }
  }

  set(key, value) {
    const keyIndex = findKeyIndex(this._entries, key);
    const valueIndex = findValueIndex(this._entries, value);

    if (keyIndex !== -1) {
      if (this._entries[keyIndex].value === value) {
        return;
      }

      if (valueIndex !== -1 && valueIndex !== keyIndex) {
        throw new ValueDuplicationError(value, 'set');
      }

      this._entries[keyIndex].value = value;
      return;
    }

    if (valueIndex !== -1) {
      throw new ValueDuplicationError(value, 'set');
    }

    this._entries.push({ key, value });
  }

  clear() {
    this._entries = [];
  }

  toString() {
    return formatBidictRepresentation(this._entries);
  }
}

