import { parseCliArguments } from './lib/argv-parser.mjs';
import { Bidict, collapseLiteralPairs } from './lib/bidict.mjs';
import { getProgramName } from './lib/cli-spec.mjs';
import { CliSignal, ValueDuplicationError, formatValueDuplicationTraceback } from './lib/errors.mjs';

function write(streamName, text) {
  if (streamName === 'stderr') {
    process.stderr.write(text);
    return;
  }

  process.stdout.write(text);
}

function printLine(text) {
  write('stdout', `${text}\n`);
}

function run() {
  const programName = getProgramName(process.argv[1]);
  let args;

  try {
    args = parseCliArguments(process.argv.slice(2), programName);
  } catch (error) {
    if (error instanceof CliSignal) {
      write(error.stream, error.text);
      return error.code;
    }

    throw error;
  }

  try {
    const b = new Bidict(
      collapseLiteralPairs([
        [args.k1, args.v1],
        [args.k2, args.v2],
      ]),
    );

    printLine(b.toString());
    b.set(args.k3, args.v3);
    printLine(b.toString());
    b.clear();
    printLine(b.toString());
    b.set('new', 100n);
    printLine(b.toString());
    return 0;
  } catch (error) {
    if (error instanceof ValueDuplicationError) {
      write('stderr', formatValueDuplicationTraceback(error));
      return 1;
    }

    throw error;
  }
}

