} from './errors.mjs';

const PYTHON_INT_PATTERN = /^[+-]?\d(?:_?\d)*$/;

function resolveLongOption(tokenName) {
  if (tokenName === HELP_LONG_NAME) {
    return { kind: 'help', name: HELP_LONG_NAME };
  }

  for (const spec of ARGUMENT_SPECS) {
    if (spec.name === tokenName) {
      return { kind: 'option', spec };
    }
  }

  const matches = [];

  if (HELP_LONG_NAME.startsWith(tokenName)) {
    matches.push({ kind: 'help', name: HELP_LONG_NAME });
  }

  for (const spec of ARGUMENT_SPECS) {
    if (spec.name.startsWith(tokenName)) {
      matches.push({ kind: 'option', spec, name: spec.name });
    }
  }

  if (matches.length === 1) {
    return matches[0];
  }

  if (matches.length > 1) {
    return {
      kind: 'ambiguous',
      matches: matches.map((match) => match.name),
    };
  }

  return { kind: 'unknown' };
}

function isNegativeIntegerLike(token) {
  return /^-\d(?:_?\d)*$/.test(token);
}

function isOptionLikeToken(token) {
  if (token === HELP_SHORT_NAME || (token.startsWith('-h') && !token.startsWith('--'))) {
    return true;
  }

  if (token.startsWith('--')) {
    return true;
  }

  return token.startsWith('-') && !isNegativeIntegerLike(token);
}

function parsePythonInt(optionName, rawValue, programName) {
  if (!PYTHON_INT_PATTERN.test(rawValue)) {
    throw new CliSignal(2, 'stderr', `${buildErrorText(programName, formatInvalidIntValue(optionName, rawValue))}\n`);
  }

  return BigInt(rawValue.replace(/_/g, ''));
}

export function parseCliArguments(argv, programName) {
  const values = Object.create(null);
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === HELP_SHORT_NAME || (token.startsWith('-h') && !token.startsWith('--'))) {
      throw new CliSignal(0, 'stdout', `${buildHelpText(programName)}\n`);
    }

    if (token.startsWith('--')) {
      const equalsIndex = token.indexOf('=');
      const optionToken = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
      const explicitArgument = equalsIndex === -1 ? null : token.slice(equalsIndex + 1);
      const resolution = resolveLongOption(optionToken);

