      }

      if (resolution.kind === 'unknown') {
        extras.push(token);
        continue;
      }

      if (resolution.kind === 'help') {
        if (explicitArgument !== null) {
          throw new CliSignal(2, 'stderr', `${buildErrorText(programName, formatIgnoredExplicitArgument(explicitArgument))}\n`);
        }

        throw new CliSignal(0, 'stdout', `${buildHelpText(programName)}\n`);
      }

      let rawValue = explicitArgument;

      if (rawValue === null) {
        const nextToken = argv[index + 1];

        if (nextToken === undefined || isOptionLikeToken(nextToken)) {
          throw new CliSignal(2, 'stderr', `${buildErrorText(programName, `argument ${resolution.spec.name}: expected one argument`)}\n`);
