    }

    extras.push(token);
  }

  const missing = [];

  for (const spec of ARGUMENT_SPECS) {
    if (spec.required && !(spec.key in values)) {
      missing.push(spec.name);
    }
  }

  if (missing.length > 0) {
    throw new CliSignal(
      2,
      'stderr',
      `${buildErrorText(programName, `the following arguments are required: ${missing.join(', ')}`)}\n`,
    );
  }

  if (extras.length > 0) {
    throw new CliSignal(2, 'stderr', `${buildErrorText(programName, `unrecognized arguments: ${extras.join(' ')}`)}\n`);
  }

  return values;
}

